from pathlib import Path
import datetime, hashlib, json, os, plistlib, pwd, re, socket, stat, subprocess, sys, zipfile
HOST = __HOST_JSON__
IDENTITY_ONLY = __IDENTITY_ONLY__
MAX_HASH_FILE = 64 * 1024 * 1024
remaining_hash_bytes = 128 * 1024 * 1024

def sha(data): return hashlib.sha256(data).hexdigest()
def bounded_file(path, limit=65536):
    with open(path, 'rb') as source:
        data = source.read(limit + 1)
    if len(data) > limit: raise ValueError('file exceeds fixed read budget')
    return data
def version(value):
    return dict(device=value.st_dev, inode=value.st_ino, size=value.st_size,
                mode=oct(stat.S_IMODE(value.st_mode)), uid=value.st_uid, gid=value.st_gid,
                mtime_ns=str(value.st_mtime_ns), ctime_ns=str(value.st_ctime_ns))
def metadata(path):
    global remaining_hash_bytes
    path=Path(path); row={'path':str(path)}
    try:
        original=path.lstat(); real=path.resolve(strict=True)
        current=real.stat()
        row.update(invocation_kind='symlink' if stat.S_ISLNK(original.st_mode) else 'direct',
                   realpath=str(real), kind='file' if stat.S_ISREG(current.st_mode) else 'directory' if stat.S_ISDIR(current.st_mode) else 'other',
                   version=version(current))
        if stat.S_ISREG(current.st_mode):
            if current.st_size <= MAX_HASH_FILE and current.st_size <= remaining_hash_bytes:
                fd=os.open(real,os.O_RDONLY|os.O_CLOEXEC|os.O_NOFOLLOW)
                try:
                    before=os.fstat(fd); hasher=hashlib.sha256(); total=0
                    while True:
                        block=os.read(fd,min(1024*1024,MAX_HASH_FILE+1-total))
                        if not block:break
                        total+=len(block); assert total<=MAX_HASH_FILE
                        hasher.update(block)
                    after=os.fstat(fd)
                    stable=version(before)==version(after) and total==before.st_size
                    remaining_hash_bytes-=total
                    row['hash_stable']=stable
                    if stable:row['sha256']=hasher.hexdigest()
                finally:os.close(fd)
            else:row['sha256_not_computed']='64 MiB per file / 128 MiB total bound'
        if real.suffix.lower()=='.app' and real.is_dir():
            plist=real/'Contents/Info.plist'
            if plist.is_file():
                info=plistlib.loads(bounded_file(plist))
                row['bundle_version']={key:info[key] for key in ('CFBundleIdentifier','CFBundleShortVersionString','CFBundleVersion') if key in info}
        if real.is_dir() and 'ghidra' in real.name.lower():
            properties=real/'Ghidra/application.properties'
            if properties.is_file():
                data=bounded_file(properties)
                row['application_properties_sha256']=sha(data)
                row['application_properties']=[line for line in data.decode('utf-8').splitlines()
                    if line.startswith(('application.name=','application.version=','application.release.name=','application.build.date='))]
    except (OSError,ValueError,AssertionError) as error:
        row['error']=dict(type=type(error).__name__,detail=str(error))
    return row

system=os.uname()
identity=dict(system=system.sysname,release=system.release,machine=system.machine,
              effective_uid=os.geteuid(),operator_home=pwd.getpwuid(os.getuid()).pw_dir)
if sys.platform=='darwin':
    try:
        run=subprocess.run(['/usr/sbin/ioreg','-rd1','-c','IOPlatformExpertDevice','-a'],capture_output=True,check=True,timeout=10)
        assert len(run.stdout)<=65536
        values=plistlib.loads(run.stdout)
        uuids=[value['IOPlatformUUID'] for value in values if 'IOPlatformUUID' in value]
        assert len(uuids)==1
        identity['platform_uuid_sha256']=sha(uuids[0].strip().lower().encode('ascii'))
        boot=subprocess.run(['/usr/sbin/sysctl','-n','kern.bootsessionuuid'],capture_output=True,text=True,check=True,timeout=5)
        identity['boot_session_uuid']=boot.stdout.strip()
    except Exception as error:identity['identity_error']=dict(type=type(error).__name__,detail=str(error))
else:
    for name,path in (('machine_id_sha256','/etc/machine-id'),('boot_id','/proc/sys/kernel/random/boot_id')):
        try:
            data=bounded_file(path,256).strip()
            identity[name]=sha(data.lower()) if name.endswith('sha256') else data.decode('ascii')
        except Exception as error:identity[name+'_error']=dict(type=type(error).__name__,detail=str(error))
result=dict(schema='hepta.rea.provider-host-inventory.v1',configured_host=HOST,
            observed_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),
            identity=identity,read_only=True,licensed_applications_launched=False,
            software_installed=False,production_services_restarted=False,
            scope='identity only for alias deduplication' if IDENTITY_ONLY else 'bounded PATH and named shallow installation checks; absence is not a global installation or license claim')
if not IDENTITY_ONLY:
    names=('idat','ida64','hopper','Hopper','frida','frida-ps','jadx','adb','gdb','lldb')
    tools={}
    for name in names:
        try:
            run=subprocess.run(['/bin/sh','-c','command -v '+name],capture_output=True,text=True,timeout=5)
            found=run.stdout.strip()
            tools[name]=dict(found=run.returncode==0 and bool(found),lookup='command -v')
            if tools[name]['found']:
                tools[name]['file']=metadata(found)
        except Exception as error:tools[name]=dict(error=type(error).__name__)
    result['path_tools']=tools
    home=Path(identity['operator_home'])
    roots=[Path('/opt'),Path('/Applications'),home/'Downloads',home/'Applications']
    match=re.compile(r'(^|[^a-z])(ida(?:64|t|t64|pro)?|hopper|ghidra|jadx|frida|android(?:[-_ ]?sdk)?|platform[-_ ]?tools|chrome|chromium|electron|gdb|lldb|google)([^a-z]|$)',re.I)
    scans=[]
    for root in roots:
        row={'root':str(root),'max_depth':2,'max_entries_per_directory':2048,'matched':[],'truncated':False}
        queue=[(root,0)]
        while queue:
            directory,depth=queue.pop(0)
            try:
                with os.scandir(directory) as entries:
                    for count,entry in enumerate(entries):
                        if count>=2048:row['truncated']=True;break
                        if not match.search(entry.name):continue
                        row['matched'].append(metadata(entry.path))
                        if depth<1 and entry.is_dir(follow_symlinks=False) and not entry.name.lower().endswith('.app'):
                            queue.append((Path(entry.path),depth+1))
                        if len(row['matched'])>=96:
                            row['truncated']=True;queue=[];break
            except FileNotFoundError:
                if directory==root:row['root_exists']=False
            except OSError as error:row.setdefault('errors',[]).append(dict(path=str(directory),error=type(error).__name__))
        scans.append(row)
    result['shallow_installation_checks']=scans
    if HOST=='desktop':
        engine_root=Path('/home/qian-qi/work/hepta-rea-engines-20261103-r1')
        paths=[engine_root/'ghidra/ghidra_12.2_PUBLIC',engine_root/'jadx/bin/jadx',
               engine_root/'jadx/lib/jadx-1.5.6-all.jar',engine_root/'jdk25/jdk-25.0.5+8/release',
               Path('/usr/lib/jvm/java-21-openjdk-amd64/release'),Path('/opt/google/chrome/chrome')]
        result['previously_observed_explicit_engine_paths']=[metadata(path) for path in paths]
        for path in (paths[3],paths[4]):
            if path.is_file():
                data=bounded_file(path)
                result.setdefault('jdk_release_metadata',[]).append(dict(path=str(path),sha256=sha(data),
                    properties=[line for line in data.decode().splitlines() if line.startswith(('JAVA_VERSION=','JAVA_RUNTIME_VERSION=','IMPLEMENTOR=','OS_ARCH='))]))
        if paths[2].is_file():
            try:
                with zipfile.ZipFile(paths[2]) as archive:
                    with archive.open('META-INF/MANIFEST.MF') as manifest:
                        data=manifest.read(65537);assert len(data)<=65536
                result['jadx_manifest_metadata']=dict(path=str(paths[2]),manifest_sha256=sha(data),
                    version_lines=[line for line in data.decode().splitlines() if line.startswith(('Implementation-Version:','Specification-Version:','Main-Class:'))])
            except Exception as error:result['jadx_manifest_metadata']=dict(error=type(error).__name__)
    daemons=[]
    if sys.platform=='darwin':
        try:
            found=subprocess.run(['/usr/bin/pgrep','-x','adb'],capture_output=True,text=True,timeout=5)
            for text in found.stdout.splitlines()[:32]:
                pid=int(text)
                command=subprocess.run(['/bin/ps','-p',str(pid),'-o','command='],capture_output=True,text=True,timeout=5).stdout.strip()
                argv=command.split()
                if 'server' not in argv or not ('fork-server' in argv or 'nodaemon' in argv):continue
                started=subprocess.run(['/bin/ps','-p',str(pid),'-o','lstart='],capture_output=True,text=True,timeout=5).stdout.strip()
                daemons.append(dict(pid=pid,server_role_observed=True,start_time=started,
                                    executable=argv[0] if argv else None))
        except Exception as error:result['adb_daemon_inspection_error']=dict(type=type(error).__name__,detail=str(error))
    else:
        try:
            with os.scandir('/proc') as entries:
                for count,entry in enumerate(entries):
                    if count>=65536:raise ValueError('proc entry bound exceeded')
                    if not entry.name.isdigit():continue
                    p=Path(entry.path)
                    try:
                        if bounded_file(p/'comm',256).strip()!=b'adb':continue
                        argv=[x.decode('utf-8','replace') for x in bounded_file(p/'cmdline',32768).split(b'\0') if x]
                        if 'server' not in argv or not ('fork-server' in argv or 'nodaemon' in argv):continue
                        fields=bounded_file(p/'stat',16384).decode().rsplit(')',1)[1].split()
                        if fields[0] in ('Z','X'):continue
                        daemons.append(dict(pid=int(entry.name),server_role_observed=True,start_ticks=int(fields[19]),
                                            owner_uid=p.stat().st_uid,executable=os.readlink(p/'exe')))
                    except (OSError,ValueError):continue
        except Exception as error:result['adb_daemon_inspection_error']=dict(type=type(error).__name__,detail=str(error))
    adb=dict(existing_daemons=daemons,client_invoked=False,daemon_started_or_restarted=False,
             transport_selected=False,device_commands_sent=False,serials_recorded_as='sha256 only',
             method='existing loopback ADB smart-socket host:version and host:devices-l only')
    def adb_query(service):
        request=service.encode('ascii')
        def take(connection,n):
            data=b''
            while len(data)<n:
                block=connection.recv(n-len(data))
                if not block:raise EOFError('existing ADB server closed early')
                data+=block
            return data
        with socket.create_connection(('127.0.0.1',5037),timeout=1.5) as connection:
            connection.settimeout(1.5)
            connection.sendall(('%04x'%len(request)).encode('ascii')+request)
            status=take(connection,4)
            if status not in (b'OKAY',b'FAIL'):raise ValueError('unexpected ADB status')
            size=int(take(connection,4),16)
            if size>65536:raise ValueError('ADB payload bound exceeded')
            data=take(connection,size)
            if status==b'FAIL':raise ValueError('existing ADB server refused read-only query')
            return data
    if not daemons:
        adb.update(state='not_probed',reason='No existing adb server process was observed; no client was invoked.')
    else:
        try:
            protocol=adb_query('host:version')
            payload=adb_query('host:devices-l')
            devices=[]
            for line in payload.decode('utf-8').splitlines():
                parts=line.split()
                if len(parts)<2:raise ValueError('invalid existing-server device row')
                item=dict(serial_sha256=sha(parts[0].encode()),state=parts[1])
                for field in parts[2:]:
                    key,sep,value=field.partition(':')
                    if sep and key in ('product','model','device','transport_id','usb'):item[key]=value
                devices.append(item)
            adb.update(state='observed_existing_server',endpoint='127.0.0.1:5037',
                       protocol_version_hex=protocol.decode('ascii'),devices=devices,device_count=len(devices),
                       response_sha256=sha(payload),response_bytes=len(payload),
                       evidence_scope='server-reported endpoints only; no device authentication or dynamic runtime qualification')
        except Exception as error:
            adb.update(state='not_probed',reason='Existing daemon observed but read-only default-port protocol observation did not complete',
                       error=dict(type=type(error).__name__,detail=str(error)))
    result['adb']=adb
print(json.dumps(result,separators=(',',':')),flush=True)
